Actionscript.script:
_parent.UpdateBigSmallState("技能中","重力井中");
if(_parent.技能浮空 == true)
{
   if(_root.gameworld[_root.控制目标].Z轴坐标 - _root.gameworld[_root.控制目标]._y >= 30)
   {
      this.onEnterFrame = function()
      {
         if(_root.gameworld[_root.控制目标].Z轴坐标 - _root.gameworld[_root.控制目标]._y >= 30)
         {
            _parent.垂直速度 += 20;
            _root.gameworld[_root.控制目标]._y += _parent.垂直速度;
            if(_root.gameworld[_root.控制目标]._y > _root.gameworld[_root.控制目标].Z轴坐标)
            {
               _root.gameworld[_root.控制目标]._y = _root.gameworld[_root.控制目标].Z轴坐标;
            }
            stop();
         }
         else
         {
            if(_parent.flySpeed > 0)
            {
               _parent.flySpeed = 0;
            }
            play();
            delete this.onEnterFrame;
         }
      };
   }
}

function 攻击时移动(慢速度, 快速度)
{
   if(_parent.方向 == "右")
   {
      if(Key.isDown(_parent.右键) == true)
      {
         _parent.移动("右",快速度);
      }
      else
      {
         _parent.移动("右",慢速度);
      }
   }
   else if(_parent.方向 == "左")
   {
      if(Key.isDown(_parent.左键) == true)
      {
         _parent.移动("左",快速度);
      }
      else
      {
         _parent.移动("左",慢速度);
      }
   }
   if(快速度 == 6)
   {
      if(Key.isDown(_parent.上键) == true)
      {
         _parent.移动("上",1);
      }
      else if(Key.isDown(_parent.下键) == true)
      {
         _parent.移动("下",1);
      }
   }
}
function 攻击时可改变移动方向(速度)
{
   if(Key.isDown(_parent.右键) == true)
   {
      _parent.方向改变("右");
   }
   else if(Key.isDown(_parent.左键) == true)
   {
      _parent.方向改变("左");
   }
   if(_parent.方向 == "右")
   {
      _parent.移动("右",速度);
   }
   else if(_parent.方向 == "左")
   {
      _parent.移动("左",速度);
   }
}
function 攻击时斜向移动(慢速度, 快速度)
{
   if(_parent.方向 == "右")
   {
      if(Key.isDown(_parent.右键) == true)
      {
         _parent.移动("右",快速度);
      }
      else
      {
         _parent.移动("右",慢速度);
      }
   }
   else if(_parent.方向 == "左")
   {
      if(Key.isDown(_parent.左键) == true)
      {
         _parent.移动("左",快速度);
      }
      else
      {
         _parent.移动("左",慢速度);
      }
   }
   if(Key.isDown(_parent.上键) == true)
   {
      _parent.移动("上",快速度);
   }
   else if(Key.isDown(_parent.下键) == true)
   {
      _parent.移动("下",快速度);
   }
}
function 攻击时可斜向改变移动方向(速度)
{
   if(Key.isDown(_parent.右键) == true)
   {
      _parent.方向改变("右");
   }
   else if(Key.isDown(_parent.左键) == true)
   {
      _parent.方向改变("左");
   }
   if(_parent.方向 == "右")
   {
      _parent.移动("右",速度);
   }
   else if(_parent.方向 == "左")
   {
      _parent.移动("左",速度);
   }
   if(Key.isDown(_parent.上键) == true)
   {
      _parent.移动("上",速度 / 2);
   }
   else if(Key.isDown(_parent.下键) == true)
   {
      _parent.移动("下",速度 / 2);
   }
}
function 攻击时斜向移动(慢速度, 快速度)
{
   if(_parent.方向 == "右")
   {
      if(Key.isDown(_parent.右键) == true)
      {
         _parent.移动("右",快速度);
      }
      else
      {
         _parent.移动("右",慢速度);
      }
   }
   else if(_parent.方向 == "左")
   {
      if(Key.isDown(_parent.左键) == true)
      {
         _parent.移动("左",快速度);
      }
      else
      {
         _parent.移动("左",慢速度);
      }
   }
   if(Key.isDown(_parent.上键) == true)
   {
      _parent.移动("上",快速度);
   }
   else if(Key.isDown(_parent.下键) == true)
   {
      _parent.移动("下",快速度);
   }
}
function 攻击时可斜向改变移动方向2(速度, 上下)
{
   if(Key.isDown(_parent.右键) == true)
   {
      _parent.方向改变("右");
   }
   else if(Key.isDown(_parent.左键) == true)
   {
      _parent.方向改变("左");
   }
   if(_parent.方向 == "右")
   {
      _parent.移动("右",速度 / 2);
   }
   else if(_parent.方向 == "左")
   {
      _parent.移动("左",速度 / 2);
   }
   if(上下 > 0)
   {
      _parent.移动("上",速度);
   }
   else if(上下 < 0)
   {
      _parent.移动("下",速度);
   }
}
if(_root.temp_player_y > 0 and _parent._name == _root.gameworld[_root.控制目标]._name)
{
   _root.是否阴影 = false;
   _parent.技能浮空 = true;
   _root.gameworld[_root.控制目标]._y = _root.temp_player_y;
   落地 = false;
   _parent.浮空 = true;
   this.onEnterFrame = function()
   {
      _parent._y += _parent.垂直速度;
      _root.temp_player_y = _parent._y;
      _parent.垂直速度 += _root.重力加速度;
      if(_parent.跳跃中上下方向 == "上")
      {
         _parent.跳跃上下移动("上",_parent.跳横移速度 / 2);
      }
      else if(_parent.跳跃中上下方向 == "下")
      {
         _parent.跳跃上下移动("下",_parent.跳横移速度 / 2);
      }
      if(_parent.跳跃中左右方向 == "右")
      {
         _parent.移动("右",_parent.跳横移速度);
      }
      else if(_parent.跳跃中左右方向 == "左")
      {
         _parent.移动("左",_parent.跳横移速度);
      }
      if(_parent._y >= _parent.Z轴坐标)
      {
         _parent._y = _parent.Z轴坐标;
         _root.temp_player_y = _parent._y;
         落地 = true;
         _parent.浮空 = false;
         _root.是否阴影 = true;
         _parent.技能浮空 = false;
         delete this.onEnterFrame;
      }
   };
}

if(_parent.技能名 != "寸拳")
{
   _parent.动画完毕();
}
_parent.攻击呐喊();

if(_parent.已使用铁布衫 != true)
{
   _parent.防御力 *= 1 + 0.05 * _parent.技能等级;
   _root.发布消息("防御力上升" + 5 * _parent.技能等级 + "%！目前防御力为" + _parent.防御力 + "点！");
}
_parent.已使用铁布衫 = true;

_parent.UpdateBigSmallState("技能中","震地中");
if(_parent.技能浮空 == true)
{
   if(_root.gameworld[_root.控制目标].Z轴坐标 - _root.gameworld[_root.控制目标]._y >= 30)
   {
      this.onEnterFrame = function()
      {
         if(_root.gameworld[_root.控制目标].Z轴坐标 - _root.gameworld[_root.控制目标]._y >= 30)
         {
            _parent.垂直速度 += 20;
            _root.gameworld[_root.控制目标]._y += _parent.垂直速度;
            if(_root.gameworld[_root.控制目标]._y > _root.gameworld[_root.控制目标].Z轴坐标)
            {
               _root.gameworld[_root.控制目标]._y = _root.gameworld[_root.控制目标].Z轴坐标;
            }
            stop();
         }
         else
         {
            if(_parent.flySpeed > 0)
            {
               _parent.flySpeed = 0;
            }
            play();
            delete this.onEnterFrame;
         }
      };
   }
}

if(_parent.已使用兴奋剂 != true)
{
   _parent.hp -= 10;
   _root.主角hp显示界面.刷新显示();
   _parent.空手攻击力 *= 1 + 0.05 * _parent.技能等级;
   _parent.行走X速度 *= 1 + 0.05 * _parent.技能等级;
   _parent.行走Y速度 *= 1 + 0.05 * _parent.技能等级;
   _parent.跑X速度 *= 1 + 0.05 * _parent.技能等级;
   _parent.跑Y速度 *= 1 + 0.05 * _parent.技能等级;
   _parent.被击硬直度 /= 2;
   _parent.起跳速度 *= 1 + 0.02 * _parent.技能等级;
   _root.发布消息("已注射兴奋剂，移动速度提升,一个场景内有效。");
}
_parent.已使用兴奋剂 = true;

_parent.UpdateBigSmallState("技能中","凶斩中");
if(_parent.技能浮空 == true)
{
   gotoAndPlay(336);
}

