onClipEvent(load){
   _parent._parent.skillShadow = this;
   if(_root.是否阴影 == true or _parent.技能浮空 == false)
   {
      this._visible = 0;
   }
   else if(_parent.技能浮空 == true)
   {
      if(!_parent._parent.飞行浮空)
      {
         this._y = 233.05 + (_parent._parent.起始Y - _parent._parent._y - _parent._parent.垂直速度) * 3.5;
      }
      this._visible = 1;
   }
}
